def transform(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    cells={}
    for r_ in range(h):
        for c_ in range(w):
            cells.setdefault(g[r_][c_],[]).append((r_,c_))
    barc=min((c for c in cells if c!=bg and len(cells[c])>1),key=lambda c:0)
    ptc=min(cells,key=lambda c: (c==bg, c==barc, len(cells[c])))
    bars=sorted(cells[barc]); pts=cells[ptc]
    segs=[];cur=[bars[0]]
    for b in bars[1:]:
        p=cur[-1]
        if (b[0]==p[0] and b[1]==p[1]+1) or (b[1]==p[1] and b[0]==p[0]+1): cur.append(b)
        else: segs.append(cur);cur=[b]
    segs.append(cur)
    horiz=all(b[0]==segs[0][0][0] for b in segs[0])
    out=[r[:] for r in g]; ptsset=set(pts)
    for p in pts:
        if horiz:
            sA,sB=segs
            axes={id(s):[b[1] for b in s] for s in segs}
            if p[1] in axes[id(sA)]: near,far=sA,sB
            else: near,far=sB,sA
            idx=[b[1] for b in near].index(p[1])
            farcol=[b[1] for b in far][idx]
            for col,frow in ((p[1],near[0][0]),(farcol,far[0][0])):
                orow = sB[0][0] if frow==sA[0][0] else sA[0][0]
                step=1 if orow>frow else -1
                r=frow+step
                while 0<=r<h:
                    if (r,col) in ptsset: out[r][col]=4; break
                    if g[r][col]==barc: break
                    out[r][col]=ptc
                    if r==orow: break
                    r+=step
        else:
            sA,sB=segs
            if p[0] in [b[0] for b in sA]: near,far=sA,sB
            else: near,far=sB,sA
            idx=[b[0] for b in near].index(p[0])
            farrow=[b[0] for b in far][idx]
            for row,fcol in ((p[0],near[0][1]),(farrow,far[0][1])):
                ocol = sB[0][1] if fcol==sA[0][1] else sA[0][1]
                step=1 if ocol>fcol else -1
                c=fcol+step
                while 0<=c<w:
                    if (row,c) in ptsset: out[row][c]=4; break
                    if g[row][c]==barc: break
                    out[row][c]=ptc
                    if c==ocol: break
                    c+=step
    return out

